func letterCombinations(digits string) []string {
    if len(digits) == 0 {
        return nil
    }
    phone := [10]string{
        "", "", "abc", "def", "ghi", "jkl",
        "mno", "pqrs", "tuv", "wxyz",
    }
    var res []string
    var path []byte
    var backtrack func(int)
    backtrack = func(idx int) {
        if idx == len(digits) {
            res = append(res, string(path))
            return
        }
        letters := phone[digits[idx]-'0']
        for i := 0; i < len(letters); i++ {
            path = append(path, letters[i])
            backtrack(idx + 1)
            path = path[:len(path)-1]
        }
    }
    backtrack(0)
    return res
}
